function compute(inputs) {
  const z = inputs.logits;
  const T = inputs.T;
  const n = z.length;
  // Compute exp(z_i / T)
  const expZ = z.map(zi => Math.exp(zi / T));
  const sumExp = expZ.reduce((a, b) => a + b, 0);
  const q = expZ.map(e => e / sumExp);
  // Build table
  const table = {
    columns: ['Class', 'z_i', 'exp(z_i/T)', 'q_i'],
    rows: z.map((zi, i) => [i+1, zi.toFixed(2), expZ[i].toFixed(4), q[i].toFixed(4)])
  };
  // Insight
  const maxQ = Math.max(...q);
  const minQ = Math.min(...q);
  const uniform = 1/n;
  let insight = '';
  if (T > 5) {
    insight = `High T (${T.toFixed(1)}) makes distribution nearly uniform (each ~${uniform.toFixed(3)}).`;
  } else if (T < 0.5) {
    insight = `Low T (${T.toFixed(1)}) makes distribution sharp: max prob = ${maxQ.toFixed(3)}.`;
  } else {
    insight = `Moderate T (${T.toFixed(1)}): max prob = ${maxQ.toFixed(3)}, min prob = ${minQ.toFixed(3)}.`;
  }
  return {
    q: q,
    table: table,
    insight: insight
  };
}
